import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
const available = existsSync(new URL('../numbers.mjs', import.meta.url));
test('numbers contract', { todo: available ? false : 'numbers branch not delivered' }, async () => {
  if (!available) return;
  const { sumIntegers } = await import('../numbers.mjs');
  assert.equal(sumIntegers('2,-5,1'), -2);
  assert.equal(sumIntegers(' 10 , -2 , 3 '), 11);
  for (const input of ['', '1,,2', '1.5', 'oops', '9007199254740992']) assert.throws(() => sumIntegers(input));
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
const available = existsSync(new URL('../text.mjs', import.meta.url));
test('text contract', { todo: available ? false : 'text branch not delivered' }, async () => {
  if (!available) return;
  const { normalizeWhitespace } = await import('../text.mjs');
  assert.equal(normalizeWhitespace('  A\tB\nC  '), 'A B C');
  assert.equal(normalizeWhitespace('\u00a0Straße\u2003東京\u00a0'), 'Straße 東京');
  assert.equal(normalizeWhitespace(''), '');
  assert.equal(normalizeWhitespace(' \t\n '), '');
});
